// Writes the final Dart artifact from the Style Dictionary JSON
// intermediate (spec `design-tokens`, tasks 2.3/2.4).
//
// Why a dedicated step instead of the built-in `flutter/class.dart`
// format: the generated file must be
//   * a single `abstract final class` of pure const data (Decision D3),
//   * a Dart-format-clean file (CI runs `dart format --set-exit-if-changed`
//     over the Flutter tree, so the generated file must already be
//     canonical),
//   * byte-stable (no timestamps; tokens sorted by name).
// The JSON intermediate from Style Dictionary (`design_tokens.flat.json`,
// transforms already applied: camelCase names, `Color(0x…)` literals) is
// far more robust to consume than parsing Dart source back.
//
// Target: `frontend-flutter/lib/design/gen/design_tokens.g.dart`
// (override the output directory with $DESIGN_TOKENS_OUT_DIR — used by the
// CI drift gate to regenerate into a throwaway directory).

import { readFileSync, mkdirSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = fileURLToPath(new URL('.', import.meta.url));
const repoRoot = resolve(here, '..');
const intermediate = join(repoRoot, 'design', 'build', 'design_tokens.flat.json');

const outDir =
  process.env.DESIGN_TOKENS_OUT_DIR !== undefined &&
  process.env.DESIGN_TOKENS_OUT_DIR !== ''
    ? resolve(repoRoot, process.env.DESIGN_TOKENS_OUT_DIR)
    : join(repoRoot, 'frontend-flutter', 'lib', 'design', 'gen');
const outFile = join(outDir, 'design_tokens.g.dart');

if (!existsSync(intermediate)) {
  console.error(
    `dart-artifact: missing Style Dictionary intermediate "${intermediate}" — ` +
      'run `style-dictionary build --config design/style-dictionary.config.json` first.',
  );
  process.exit(1);
}

/** @type {Record<string, string | number>} */
const tokens = JSON.parse(readFileSync(intermediate, 'utf8'));

/** Dart literal + explicit static type for one transformed token value. */
function dartLiteral(value) {
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) {
      throw new Error(`non-finite number in token intermediate: ${value}`);
    }
    // Always emit doubles (`2` → `2.0`) so Dart infers `double`, not `int`.
    const s = String(value);
    return { type: 'double', literal: s.includes('.') ? s : `${s}.0` };
  }
  if (typeof value === 'string' && /^Color\(0x[0-9A-F]{8}\)$/.test(value)) {
    return { type: 'Color', literal: value };
  }
  if (typeof value === 'object' && value !== null) {
    // DTCG 2025.10 structured values reaching the intermediate without a
    // platform transform. Style Dictionary converts srgb color objects to
    // `Color(0xAARRGGBB)` via `color/hex8flutter`; dimensions stay objects
    // because we apply no size transform — unit "px" maps 1:1 to a Dart
    // double (logical px).
    if (
      typeof value.value === 'number' &&
      Number.isFinite(value.value) &&
      value.unit === 'px'
    ) {
      return dartLiteral(value.value);
    }
    if (
      value.colorSpace === 'srgb' &&
      Array.isArray(value.components) &&
      value.components.length === 3 &&
      value.components.every((c) => typeof c === 'number' && c >= 0 && c <= 1)
    ) {
      const alpha =
        value.alpha === undefined || value.alpha === null
          ? 255
          : Math.round(value.alpha * 255);
      const rgb = value.components
        .map((c) => Math.round(c * 255).toString(16).padStart(2, '0'))
        .join('')
        .toUpperCase();
      const a = alpha.toString(16).padStart(2, '0').toUpperCase();
      return { type: 'Color', literal: `Color(0x${a}${rgb})` };
    }
  }
  throw new Error(`unsupported token value shape: ${JSON.stringify(value)}`);
}

const names = Object.keys(tokens).sort();
const lines = [];
for (const name of names) {
  const { type, literal } = dartLiteral(tokens[name]);
  lines.push(`  static const ${type} ${name} = ${literal};`);
}

const header = [
  '// SPDX-License-Identifier: AGPL-3.0',
  '// Copyright (C) 2024-2026 Breakdown RS Contributors',
  '// GENERATED — do not edit.',
  '//',
  '// Regenerated by `bash scripts/build-tokens.sh` from the DTCG token source',
  '// under `design/tokens/**/*.json` (Style Dictionary). Hand edits are',
  '// forbidden — regenerate instead (spec `design-tokens`, Decision D5).',
].join('\n');

const doc = [
  '/// Generated design tokens (W3C-DTCG source at `design/tokens/`).',
  '///',
  '/// Pure data only (Decision D3): const [Color] and double values. Theme',
  '/// composition and the spacing extension stay hand-authored in',
  '/// `theme.dart` / `spacing.dart` — this file is replaceable',
  '/// byte-for-byte by a re-run of the build script.',
].join('\n');

const content = [
  header,
  '',
  "import 'dart:ui' show Color;",
  '',
  doc,
  'abstract final class DesignTokens {',
  ...lines,
  '}',
  '',
].join('\n');

mkdirSync(outDir, { recursive: true });
writeFileSync(outFile, content, 'utf8');
console.log(
  `dart-artifact: wrote ${names.length} token(s) → ${outFile.replace(repoRoot + '/', '')}`,
);
